stageCss:
#stage .sa-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .sa-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .sa-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42); color:var(--accent-1);
}
#stage .sa-mark svg{ width:24px; height:24px; }
#stage .sa-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .sa-rt{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:8px; }
#stage .sa-rt b{
  color:#fff; font-family:var(--font-mono); font-size:28px; font-weight:700;
  font-variant-numeric:tabular-nums; transition:color .3s ease;
}
#stage .sa-rt.bad b{ color:var(--danger); }
#stage .sa-rt.ok b{ color:var(--success); }
#stage .sa-rt i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .sa-health{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid rgba(63,185,80,.45); background:rgba(63,185,80,.1);
  transition:border-color .3s ease, background .3s ease;
}
#stage .sa-health i{
  width:10px; height:10px; border-radius:50%; background:var(--success);
  box-shadow:0 0 12px var(--success); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .sa-health b{ color:var(--success); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .sa-health.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); }
#stage .sa-health.warn i{ background:var(--warn); box-shadow:0 0 12px var(--warn); animation-duration:.6s; }
#stage .sa-health.warn b{ color:var(--warn); }
#stage .sa-health.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.12); }
#stage .sa-health.bad i{ background:var(--danger); box-shadow:0 0 12px var(--danger); animation-duration:.45s; }
#stage .sa-health.bad b{ color:var(--danger); }

/* ============================= SCENE STACK ============================= */
#stage .sa-body{ position:relative; flex:1; min-height:0; }
#stage .sa-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .sa-sc.on{ opacity:1; transform:none; }
#stage .sa-sc.whip{ animation:sa-whip .44s cubic-bezier(.19,1,.22,1); }

#stage .sa-sync, #stage .sa-async{ display:flex; flex-direction:column; gap:14px; height:100%; }

/* ------------------------------------------------------------ end nodes -- */
#stage .sa-node{
  height:128px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .sa-node.tight{ height:116px; }
#stage .sa-node.busy{ border-color:rgba(240,166,74,.6); box-shadow:0 0 0 1px rgba(240,166,74,.22), 0 0 44px rgba(240,166,74,.14); }
#stage .sa-node.ok{ border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.2), 0 0 44px rgba(63,185,80,.12); }
#stage .sa-node.bad{
  border-color:rgba(244,74,106,.65); box-shadow:0 0 0 1px rgba(244,74,106,.24), 0 0 48px rgba(244,74,106,.16);
  animation:sa-alert 1s ease-in-out infinite;
}
#stage .sa-node-ic{
  width:56px; height:56px; border-radius:16px; flex-shrink:0; font-size:28px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338); border:1.5px solid var(--border);
}
#stage .sa-node-t{ display:flex; flex-direction:column; gap:6px; min-width:0; }
#stage .sa-node-t b{ color:#fff; font-size:26px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .sa-node-t i{ color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:600; font-style:normal; white-space:nowrap; }
#stage .sa-node-b{
  margin-left:auto; flex-shrink:0; padding:9px 17px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(240,166,74,.5); background:rgba(240,166,74,.12); color:var(--warn);
  font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:1.2px;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .sa-node-b.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.14); color:var(--success); letter-spacing:0; }
#stage .sa-node-b.bad{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.16); color:var(--danger); }

/* ------------------------------------------------------------- the line -- */
#stage .sa-link{
  position:relative; flex:1; min-height:0;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:12px;
}
#stage .sa-wire{ display:flex; flex-direction:column; align-items:center; gap:9px; }
#stage .sa-wire i{
  display:block; width:7px; height:22px; border-radius:4px;
  background:var(--warn); box-shadow:0 0 12px rgba(240,166,74,.55);
  animation:sa-pulse 1.1s linear infinite;
}
#stage .sa-wire i:nth-child(2){ animation-delay:.16s; }
#stage .sa-wire i:nth-child(3){ animation-delay:.32s; }
#stage .sa-wire i:nth-child(4){ animation-delay:.48s; }
#stage .sa-link.async .sa-wire i{ background:var(--success); box-shadow:0 0 12px rgba(63,185,80,.5); animation-duration:1.8s; }
#stage .sa-link.cut .sa-wire i{ background:var(--danger); box-shadow:0 0 12px rgba(244,74,106,.5); animation:none; opacity:.4; }
#stage .sa-link-b{
  padding:8px 18px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(240,166,74,.5); background:rgba(240,166,74,.12); color:var(--warn);
  font-family:var(--font-mono); font-size:19px; font-weight:700;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .sa-link.async .sa-link-b{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.12); color:var(--success); }
#stage .sa-link.cut .sa-link-b{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.16); color:var(--danger); }

/* ------------------------------------------------------- availability math -- */
#stage .sa-chain{ height:140px; flex-shrink:0; display:flex; align-items:center; gap:11px; }
#stage .sa-hop{
  flex:1; min-width:0; display:flex; flex-direction:column; align-items:center; gap:8px;
  padding:16px 8px; border-radius:18px; white-space:nowrap;
  background:rgba(14,20,32,.72); border:1.5px solid var(--border); color:var(--text-dim);
  font-family:var(--font-mono); font-size:17px; font-weight:600;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .sa-hop i{ color:#fff; font-size:22px; font-weight:800; font-style:normal; }
#stage .sa-hop.on{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.1); color:var(--warn); }
#stage .sa-hop.total{ flex:1.2; }
#stage .sa-hop.total.on{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.12); color:var(--danger); }
#stage .sa-hop.total.on i{ color:var(--danger); }
#stage .sa-eq{ flex-shrink:0; color:var(--text-dim); font-family:var(--font-mono); font-size:24px; font-weight:700; }

#stage .sa-math{
  height:120px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:22px;
  background:rgba(20,27,43,.6); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .sa-math.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.07); }
#stage .sa-math.ok{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.07); }
#stage .sa-math-ic{
  width:48px; height:48px; border-radius:14px; flex-shrink:0; font-size:25px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); border:1.5px solid rgba(58,160,255,.3);
}
#stage .sa-math-t{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }

/* ---------------------------------------------------------- the mailbox -- */
#stage .sa-mbox{
  height:158px; flex-shrink:0; display:flex; flex-direction:column; gap:12px; justify-content:center;
  padding:16px 20px; border-radius:26px;
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.12), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(58,160,255,.45);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .sa-mbox.full{ border-color:rgba(240,166,74,.6); box-shadow:0 0 0 1px rgba(240,166,74,.22), 0 0 50px rgba(240,166,74,.14); }
#stage .sa-mbox-h{ display:flex; align-items:center; gap:13px; }
#stage .sa-mbox-ic{
  width:46px; height:46px; border-radius:13px; flex-shrink:0; font-size:24px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.16); border:1.5px solid rgba(58,160,255,.4);
}
#stage .sa-mbox-n{ color:#fff; font-size:24px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .sa-mbox-d{ margin-left:auto; display:flex; align-items:baseline; gap:8px; white-space:nowrap; }
#stage .sa-mbox-d b{ color:var(--accent-cyan); font-family:var(--font-mono); font-size:26px; font-weight:700; font-variant-numeric:tabular-nums; }
#stage .sa-mbox-d i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .sa-mbox-b{
  flex:1; min-height:0; display:flex; align-items:center; gap:10px;
  padding:0 14px; border-radius:16px; overflow:hidden;
  background:rgba(14,20,32,.75); border:1.5px solid var(--border);
}
#stage .sa-msg{
  padding:10px 14px; border-radius:11px; white-space:nowrap; opacity:0;
  background:rgba(34,211,238,.12); border:1.5px solid rgba(34,211,238,.45); color:var(--accent-cyan);
  font-family:var(--font-mono); font-size:18px; font-weight:600;
  transition:opacity .25s ease;
}
#stage .sa-msg.on{ opacity:1; animation:msd-pop .3s cubic-bezier(.22,1,.36,1); }

/* ------------------------------------------------------------- the bill -- */
#stage .sa-cost{ height:132px; flex-shrink:0; display:flex; align-items:center; gap:11px; }
#stage .sa-c{
  flex:1; min-width:0; text-align:center; padding:18px 8px; border-radius:18px;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border); color:var(--text-dim);
  font-family:var(--font-mono); font-size:17px; font-weight:600;
  opacity:.35; filter:saturate(.2);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease, color .3s ease, background .3s ease;
}
#stage .sa-c.on{
  opacity:1; filter:none;
  border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.1); color:var(--warn);
}

#stage .sa-strip{
  height:72px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .sa-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .sa-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .sa-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); }
#stage .sa-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .sa-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .sa-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ======================= SCENE 3 · WHEN TO USE WHICH =================== */
#stage .sa-split{ display:flex; gap:16px; height:100%; }
#stage .sa-col{
  flex:1; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:16px;
  padding:26px 18px; border-radius:28px; text-align:center;
}
#stage .sa-col.sync{ background:rgba(20,27,43,.6); border:2px solid rgba(240,166,74,.45); }
#stage .sa-col.async{
  background:radial-gradient(circle at 50% 0%, rgba(63,185,80,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(63,185,80,.5);
}
#stage .sa-col-h{ font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:1.6px; white-space:nowrap; }
#stage .sa-col.sync .sa-col-h{ color:var(--warn); }
#stage .sa-col.async .sa-col-h{ color:var(--success); }
#stage .sa-col-ic{ font-size:56px; line-height:1; }
#stage .sa-col-list{ width:100%; display:flex; flex-direction:column; gap:10px; }
#stage .sa-row{
  padding:14px 10px; border-radius:13px;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border); color:var(--text-dim);
  font-size:21px; font-weight:600; line-height:1.25;
}
#stage .sa-row b{ color:#fff; font-weight:800; }
#stage .sa-col-x{
  width:100%; padding:13px 10px; border-radius:14px;
  background:rgba(240,166,74,.12); border:1.5px solid rgba(240,166,74,.45); color:var(--warn);
  font-family:var(--font-mono); font-size:17px; font-weight:700; line-height:1.3;
}
#stage .sa-col-x.ok{ background:rgba(63,185,80,.12); border-color:rgba(63,185,80,.45); color:var(--success); }

/* ========================== SCENE 4 · THE PAYOFF ======================= */
#stage .sa-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .sa-badges{ display:flex; gap:20px; }
#stage .sa-badge{
  width:120px; height:120px; border-radius:34px; font-size:54px;
  display:flex; align-items:center; justify-content:center;
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .sa-badge.sync{
  background:linear-gradient(160deg, rgba(240,166,74,.3), rgba(240,166,74,.1));
  border:2px solid rgba(240,166,74,.55);
  box-shadow:0 0 0 1px rgba(240,166,74,.24), 0 0 70px rgba(240,166,74,.24);
}
#stage .sa-badge.async{
  background:linear-gradient(160deg, rgba(63,185,80,.3), rgba(34,211,238,.12));
  border:2px solid rgba(63,185,80,.55);
  box-shadow:0 0 0 1px rgba(63,185,80,.24), 0 0 70px rgba(63,185,80,.24);
  animation-delay:.5s;
}
#stage .sa-badge-l{ color:var(--text-dim); font-family:var(--font-mono); font-size:20px; font-weight:800; letter-spacing:3px; }
#stage .sa-fin-h{ color:#fff; font-size:56px; font-weight:900; line-height:1.14; letter-spacing:-1.6px; }
#stage .sa-fin-h em{ font-style:normal; color:var(--accent-cyan); }
#stage .sa-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .sa-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(58,160,255,.42); color:var(--text-primary);
  font-size:22px; font-weight:700;
}
#stage .sa-save{
  margin-top:8px; padding:18px 26px; border-radius:20px; max-width:860px;
  background:linear-gradient(90deg, rgba(240,166,74,.16), rgba(63,185,80,.16));
  border:1.5px solid rgba(63,185,80,.5); color:#fff;
  font-size:25px; font-weight:700; line-height:1.35;
}
#stage .sa-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes sa-pulse{
  0%{ transform:translateY(-14px); opacity:0; }
  30%{ opacity:1; }
  100%{ transform:translateY(14px); opacity:0; }
}
@keyframes sa-alert{
  0%,100%{ box-shadow:0 0 0 1px rgba(244,74,106,.3), 0 0 40px rgba(244,74,106,.16); }
  50%{ box-shadow:0 0 0 1px rgba(244,74,106,.55), 0 0 80px rgba(244,74,106,.3); }
}
@keyframes sa-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
}

