var SA = window.__SA || (window.__SA = {});
SA.ramp = function(sel, from, to, ms){
  var el = MSD.q(sel); if(!el) return;
  var steps = Math.max(1, Math.round(ms / 50)), i = 0;
  var id = MSD.every(50, function(){
    i++;
    var p = Math.min(1, i / steps);
    el.textContent = String(Math.round(from + (to - from) * p));
    if(p >= 1) clearInterval(id);
  });
};

MSD.cls('.sa-sc', 'on', false);
MSD.cls('#sa-sc-sync', 'on', true);
MSD.q('#sa-app').textContent = 'checkout → shipping';
MSD.cls('#sa-rt', 'ok', false);
MSD.cls('#sa-rt', 'bad', false);
MSD.q('#sa-rt-n').textContent = '0';
MSD.cls('#sa-health', 'warn', false);
MSD.cls('#sa-health', 'bad', false);
MSD.q('#sa-health-t').textContent = 'both up';

MSD.cls('#sa-caller', 'busy', false);
MSD.cls('#sa-caller', 'bad', false);
MSD.cls('#sa-callee', 'bad', false);
MSD.q('#sa-caller-s').textContent = 'about to call shipping';
MSD.q('#sa-caller-b').textContent = 'READY';
MSD.cls('#sa-caller-b', 'bad', false);
MSD.q('#sa-callee-s').textContent = 'must be up, right now';
MSD.q('#sa-callee-b').textContent = 'LISTENING';
MSD.cls('#sa-callee-b', 'bad', false);
MSD.cls('#sa-link', 'cut', false);
MSD.q('#sa-link-b').textContent = 'dialling…';
MSD.cls('.sa-hop', 'on', false);
MSD.cls('#sa-math', 'bad', false);
MSD.cls('#sa-math', 'ok', false);
MSD.q('#sa-math-ic').textContent = '🤔';
MSD.q('#sa-math-t').textContent = 'Option A: call it and wait. Option B: leave a message and carry on.';
MSD.cls('#sa-strip', 'bad', false);
MSD.cls('#sa-strip', 'good', false);
MSD.q('#sa-strip-l').textContent = 'START';
MSD.q('#sa-strip-t').textContent = 'Same requirement. The choice is only about whether you wait for the reply.';
MSD.hide('.sa-row');
MSD.hide('.sa-fin-p');
MSD.cls('.sa-msg', 'on', false);
MSD.cls('.sa-c', 'on', false);

MSD.after(600, function(){ MSD.punch('#sa-caller', 1); MSD.sfx.blip(1); });
MSD.after(1300, function(){ MSD.punch('#sa-callee', 3); MSD.sfx.blip(3); });

var SA = window.__SA;

MSD.cls('.sa-sc', 'on', false);
MSD.cls('#sa-sc-sync', 'on', true);
MSD.cls('#sa-link', 'cut', false);
MSD.cls('#sa-caller', 'busy', true);
MSD.q('#sa-caller-s').textContent = 'holding the request open';
MSD.q('#sa-caller-b').textContent = 'WAITING';
MSD.q('#sa-callee-b').textContent = 'ANSWERING';
MSD.q('#sa-link-b').textContent = 'on the call';
MSD.cls('#sa-rt', 'ok', false);
MSD.cls('#sa-rt', 'bad', true);
MSD.cls('#sa-strip', 'good', false);
MSD.q('#sa-strip-l').textContent = 'SYNC';
MSD.q('#sa-strip-t').textContent = 'A call needs both people free at the same second. So does a synchronous API.';

SA.ramp('#sa-rt-n', 0, 612, 2300);
MSD.after(900, function(){
  MSD.cls('#sa-health', 'warn', true);
  MSD.q('#sa-health-t').textContent = 'blocked';
  MSD.punch('#sa-link', 2);
});
MSD.after(1900, function(){
  MSD.q('#sa-math-ic').textContent = '⏳';
  MSD.q('#sa-math-t').textContent = 'The user is on a spinner for the whole call, and so is a thread on your server.';
  MSD.punch('#sa-math', 4);
});

var SA = window.__SA;

MSD.cls('.sa-sc', 'on', false);
MSD.cls('#sa-sc-sync', 'on', true);
MSD.cls('#sa-caller', 'busy', true);
MSD.q('#sa-rt-n').textContent = '612';
MSD.cls('#sa-rt', 'bad', true);
MSD.cls('#sa-strip', 'good', false);
MSD.cls('#sa-strip', 'bad', true);
MSD.q('#sa-strip-l').textContent = 'COUPLED';
MSD.q('#sa-strip-t').textContent = 'Synchronous means you are only as available as everything you call.';

MSD.after(300, function(){ MSD.cls('#sa-hop-1', 'on', true); MSD.sfx.blip(1); });
MSD.after(650, function(){ MSD.cls('#sa-hop-2', 'on', true); MSD.sfx.blip(2); });
MSD.after(1000, function(){ MSD.cls('#sa-hop-3', 'on', true); MSD.sfx.blip(3); });
MSD.after(1450, function(){
  MSD.cls('#sa-hop-t', 'on', true);
  MSD.punch('#sa-hop-t', 4);
